=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to set the target brake request close below the driver request
   as long as the driver brake request is higher than required hold pressure or it's release
   gradient is slow enough */

// In case:
//  - Comfort Release is enabled
//  - And the actual driver brake request is more negative (higher) than the target request of CSM would be for a release
//  - and vehicle is stopped or (if enabled) less than some maximum speed
// Then target brake request shall be set to similar value (considering small offset) like the driver request

if(		CsmDrvOffComfortReleaseEnable == true
	&&	CsmDrvOffComfortRelease == true
	&&	CsmHoldDriveReqActive > 0
	&&	(	VehStandstill == true
		||	(FS_CSM_DriveOffEnableComfortReleaseWhileMoving == true && VVehComfort < C_CSM_DriveOffVMaxComfortRelease))
	)
{
		CsmHoldComfortReleaseATarBrk = (ADrvBrk + C_CSM_DriveOffComfortReleaseaOffset).min(0);
		if(CsmHoldComfortReleaseATarBrk < 0)
		{
			CsmHoldComfortReleaseActive = true;
		}		else
		{
			CsmHoldComfortReleaseActive = false;
		}	
		
		CsmHoldComfortReleaseEnableReactByBrkInc = false;
}
else
{
		CsmHoldComfortReleaseActive = false;
		CsmHoldComfortReleaseATarBrk = 0;
		
		CsmHoldComfortReleaseEnableReactByBrkInc = true;
}



=== Method: CsmHoldComfortReleaseActive (AbstractMethod) ===
return CsmHoldComfortReleaseActive;


=== Method: CsmHoldComfortReleaseATarBrk (AbstractMethod) ===
return CsmHoldComfortReleaseATarBrk;


=== Method: CsmHoldComfortReleaseEnableReactByBrkInc (AbstractMethod) ===
return CsmHoldComfortReleaseEnableReactByBrkInc;
